import numpy as np

def select_next_node(current_node, truck_nodes, depot_node, unvisited_nodes, distance_matrix):
    # Convert unvisited_nodes to list if it's a numpy array
    if isinstance(unvisited_nodes, np.ndarray):
        unvisited_nodes = unvisited_nodes.tolist()

    if len(unvisited_nodes) == 0:
        return None  # no nodes left (should not happen in normal operation)

    # Candidates: unvisited nodes plus the depot
    candidates = unvisited_nodes + [depot_node]

    best_saving = -np.inf
    best_node = None

    for j in unvisited_nodes:
        # Find nearest neighbor k among candidates (excluding j)
        min_dist_to_k = np.inf
        nearest_k = None
        for k in candidates:
            if k == j:
                continue
            d = distance_matrix[j, k]
            if d < min_dist_to_k:
                min_dist_to_k = d
                nearest_k = k

        # Compute saving: dist(current, j) + dist(j, k) - dist(current, k)
        saving = distance_matrix[current_node, j] + min_dist_to_k - distance_matrix[current_node, nearest_k]

        if saving > best_saving:
            best_saving = saving
            best_node = j

    # If the best saving is not positive, wait (return None)
    if best_saving > 0:
        return best_node
    else:
        return next_node
